def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    fill_ratio = item / bins
    scores = -np.abs(fill_ratio - 0.8)
    return np.where(fit_mask, scores, -np.inf)

